order, done = [], set()
while len(order) < len(deps):
    ready = [n for n in deps if n not in done and all(d in done for d in deps[n])]
    if not ready: raise ValueError("cycle detected")
    done.update(ready); order.extend(sorted(ready))
print("build order:", order)

