G = {"a": ["b"], "b": ["c"], "c": ["a"], "d": ["c"]}
def find_cycle():
    path = []
    def dfs(n):
        if n in path: return path[path.index(n):] + [n]
        path.append(n)
        for m in G[n]:
            c = dfs(m)
            if c: return c
        path.pop()
    for n in G:
        c = dfs(n)
        if c: return c
print("cycle:", find_cycle())

