G = {"base": ["lib"], "lib": ["app"], "app": ["svc"], "data": ["model"]}
def downstream(start):
    seen, stack = set(), [start]
    while stack:
        n = stack.pop()
        for m in G.get(n, []):
            if m not in seen: seen.add(m); stack.append(m)
    return seen
print("changing 'lib' affects:", sorted(downstream("lib")))

