COST = {"base": 2, "lib": 5, "app": 3, "svc": 1}
DEPS = {"app": ["lib"], "lib": ["base"], "base": [], "svc": ["app"]}
memo = {}
def longest(n):
    if n in memo: return memo[n]
    memo[n] = COST[n] + max([longest(d) for d in DEPS[n]] or [0])
    return memo[n]
crit = max(DEPS, key=longest)
print("critical path ends at %s, length %d" % (crit, longest(crit)))

